using System; 

class IterativeFibonacci 
{ 
 static void Main() 
 { 
  Console.Write("n = "); 
  int n = int.Parse(Console.ReadLine()); 

  long result = Fib(n); 
  Console.WriteLine("fib({0}) = {1}", n, result); 
 } 

 static long Fib(int n) 
 { 
  long fn = 0; 
  long fnMinus1 = 1; 
  long fnMinus2 = 1; 

  for (int i = 2; i < n; i++) 
  { 
   fn = fnMinus1 + fnMinus2; 

   fnMinus2 = fnMinus1; 
   fnMinus1 = fn; 
  } 

  return fn; 
 } 
}
