   if (nextChar == -1) 
   { 
    // End of file reached 
    PrintBuffer(writer, buffer); 
    break; 
   } 
   char ch = (char)nextChar; 
   if (ch == '<') 
   { 
    if (!inTag) 
    { 
     PrintBuffer(writer, buffer); 
    } 
    buffer.Clear(); 
    inTag = true; 
   } 
   else if (ch == '>') 
